    enhancer = ImageEnhance.Contrast(img)
    img = enhancer.enhance(2.0)
    return img

def extract_date(text):
    # Clean up text a bit for date search
    text = text.replace(' ', '')
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})',
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2})',
        r'(\d{1,2})(\d{2})(\d{4})', # 20032018 or 2032018 (if 7-8 digits)
    ]

    # Try searching for dates
    for pattern in patterns:
        matches = re.finditer(pattern, text)
        for match in matches:
            g = match.groups()
            try:
                if len(g[0]) == 4:
                    y, m_val, d = int(g[0]), int(g[1]), int(g[2])
                elif len(g[-1]) == 4:
                    d, m_val, y = int(g[0]), int(g[1]), int(g[2])
                else:
                    d, m_val, y = int(g[0]), int(g[1]), int(g[2])
                    y += 2000

                if m_val == 62: m_val = 2
                if 1 <= m_val <= 12 and 1 <= d <= 31 and 1900 <= y <= 2100:
                    return f"{y:04d}-{m_val:02d}-{d:02d}"
            except:
                continue
    return None

def extract_total_amount(text):
    lines = text.split('\n')
    lines = [line.strip() for line in lines if line.strip()]
    keywords_priority = [
        r'GRAND\s*TOTAL', r'TOTAL\s*RM', r'TOTAL:\s*RM', r'TOTAL\s*AMOUNT',
        r'TOTAL', r'AMOUNT', r'TOTAL\s*DUE', r'AMOUNT\s*DUE', r'BALANCE\s*DUE', r'NETT\s*TOTAL', r'NET\s*TOTAL'
    ]
    exclusion_keywords = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    def get_amount_from_line(line):
        match = re.findall(r'\d{1,3}(?:[ ,]\d{3})*[ .]+\d{2}', line)
        if match:
            amt_str = match[-1].replace(',', '').replace(' ', '')
            if amt_str.count('.') > 1:
                parts = amt_str.split('.')
                amt_str = "".join(parts[:-1]) + "." + parts[-1]
            return amt_str
        return None

    for kw_pattern in keywords_priority:
        for i, line in enumerate(lines):
            if re.search(kw_pattern, line, re.IGNORECASE):
                if any(re.search(r'\b' + ex.replace(' ', r'\s*') + r'\b', line, re.IGNORECASE) for ex in exclusion_keywords):
                    if kw_pattern in [r'TOTAL', r'AMOUNT']: continue
                amount = get_amount_from_line(line)
                if amount: return amount
                if i + 1 < len(lines):
                    amount = get_amount_from_line(lines[i+1])
                    if amount: return amount
    return None

img_dir = '/app/workspace/dataset/img'
files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])
results = []
for filename in files:
    img_path = os.path.join(img_dir, filename)
    try:
        img = Image.open(img_path)
        text = pytesseract.image_to_string(img)
        date = extract_date(text)
        amount = extract_total_amount(text)
        if not date or not amount:
            text_p = pytesseract.image_to_string(preprocess_image(img))
            if not date: date = extract_date(text_p)
            if not amount: amount = extract_total_amount(text_p)
        if amount:
            try: amount = "{:.2f}".format(float(amount))
            except: amount = None
        results.append((filename, date, amount))
    except Exception: results.append((filename, None, None))

wb = Workbook()
ws = wb.active
ws.title = "results"
ws.append(["filename", "date", "total_amount"])
for res in results: ws.append(res)
wb.save('/app/workspace/stat_ocr.xlsx')
